-- Rollback-only hosted verification. Simulated owner/outsider/anonymous JWT claims.
begin;
select set_config('faraios.foundation_bid',(select id::text from public.businesses where name='FaraiOS Preview Test Business'),true);
select set_config('request.jwt.claim.sub',(select owner_id::text from public.businesses where id=current_setting('faraios.foundation_bid')::uuid),true),set_config('request.jwt.claims','{"is_anonymous":false}',true);
set local role authenticated;
do $$declare bid uuid=current_setting('faraios.foundation_bid')::uuid;q uuid=gen_random_uuid();i uuid=gen_random_uuid();p uuid=gen_random_uuid();child uuid;d jsonb;c text;original jsonb;ledger jsonb;token text;denied boolean;begin
 select coalesce((select draft->>'currency' from public.business_service_catalogues where business_id=bid and environment='preview'),'ZAR') into c;
 d=jsonb_build_object('name','Fictional foundation rollback probe','email','probe@example.test','phone','','notes','Rollback only','currency',c,'items',jsonb_build_array(jsonb_build_object('name','Free assessment','quantity',1,'price',0)));
 perform public.business_quote_write(bid,'preview',q,0,'save',d,current_date+14);
 denied=false;begin perform public.business_quote_write(bid,'preview',q,1,'send',d,current_date+14);exception when raise_exception then denied=true;end;if not denied then raise exception 'FAIL legacy send bypass';end if;
 denied=false;begin perform public.business_quote_send(bid,'preview',q,1,false);exception when raise_exception then denied=true;end;if not denied then raise exception 'FAIL missing free confirmation';end if;
 perform public.business_quote_send(bid,'preview',q,1,true);
 if not exists(select 1 from public.business_quotes where id=q and status='Sent' and free_confirmed_at is not null) then raise exception 'FAIL confirmed free send';end if;
 select share_token into token from public.business_quotes where id=q;
 if public.business_quote_customer('preview',token,'Accepted')->>'status'<>'Accepted' then raise exception 'FAIL free acceptance';end if;
 d=jsonb_set(d,'{items,0,price}','25000');
 perform public.business_invoice_write(bid,'preview',i,0,'save',d,current_date+14);
 perform public.business_invoice_write(bid,'preview',i,1,'issue');
 perform public.business_invoice_payment(bid,'preview',i,p,10000,current_date,'Rollback payment');
 denied=false;begin perform public.business_invoice_write(bid,'preview',i,3,'void',null,null,null,'Correct test invoice');exception when raise_exception then denied=true;end;if not denied then raise exception 'FAIL paid void';end if;
 perform public.business_invoice_payment(bid,'preview',i,gen_random_uuid(),10000,current_date,'Rollback payment',p,'Correct test ledger');
 perform public.business_invoice_write(bid,'preview',i,4,'void',null,null,null,'Correct test invoice');
 select to_jsonb(t) into original from public.business_invoices t where id=i;
 select jsonb_agg(to_jsonb(t) order by id) into ledger from public.business_invoice_payments t where invoice_id=i;
 child=(public.business_invoice_write(bid,'preview',i,5,'replace',null,null,null,'Correct test invoice')->>'id')::uuid;
 if (public.business_invoice_write(bid,'preview',i,5,'replace',null,null,null,'Correct test invoice')->>'id')::uuid<>child then raise exception 'FAIL replacement replay';end if;
 d=jsonb_set(d,'{items,0,price}','27525');
 perform public.business_invoice_write(bid,'preview',child,1,'save',d,current_date+14);
 perform public.business_invoice_write(bid,'preview',child,2,'issue');
 if not exists(select 1 from public.business_invoice_list where id=child and replaces_id=i and total=27525 and state='Issued') then raise exception 'FAIL replacement issue';end if;
 if (select to_jsonb(t) from public.business_invoices t where id=i)<>original or (select jsonb_agg(to_jsonb(t) order by id) from public.business_invoice_payments t where invoice_id=i)<>ledger then raise exception 'FAIL history preservation';end if;
 perform set_config('faraios.foundation_invoice',i::text,true);
 denied=false;begin perform public.business_invoice_write(bid,'live',i,5,'replace',null,null,null,'Live must remain blocked');exception when raise_exception then denied=true;end;if not denied then raise exception 'FAIL environment isolation';end if;
end$$;
reset role;
select set_config('request.jwt.claim.sub','ffffffff-ffff-ffff-ffff-ffffffffffff',true);
set local role authenticated;
do $$declare denied boolean=false;begin
 if exists(select 1 from public.business_invoices) or exists(select 1 from public.business_invoice_events) or exists(select 1 from public.business_invoice_payments) then raise exception 'FAIL outsider financial read';end if;
 begin perform public.business_invoice_write(current_setting('faraios.foundation_bid')::uuid,'preview',current_setting('faraios.foundation_invoice')::uuid,5,'replace',null,null,null,'Forbidden outsider');exception when raise_exception then denied=true;end;if not denied then raise exception 'FAIL outsider replacement';end if;
 denied=false;begin perform public.business_quote_send(current_setting('faraios.foundation_bid')::uuid,'preview',gen_random_uuid(),1,true);exception when raise_exception then denied=true;end;if not denied then raise exception 'FAIL outsider quote send';end if;
end$$;
reset role;
set local role anon;
do $$declare denied boolean=false;begin
 begin perform public.business_quote_send(null,'preview',null,1,true);exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'FAIL anonymous quote send';end if;
 denied=false;begin select 1 from public.business_invoices;exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'FAIL anonymous invoice read';end if;
end$$;
reset role;
rollback;
select 'PASS: foundation hosted rollback probes; no retained fixtures' as result;
